            std::cout << "PASS case=" << c.id << " impl=" << c.impl << " n=" << c.n
                      << " threads=" << c.threads << " steps=" << c.steps << std::endl;
            r.ReleaseBuffers();
        }
        return 0;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n'; return 1;
    }
}

